S = "Hakeem Force Academy"
QS = [
(S, "Which is the longest freshwater lake in the world?", ["Lake Victoria", "Lake Tanganyika", "Lake Superior", "Lake Baikal"], 1, "Lake Tanganyika in Africa is about 676 km long, the longest freshwater lake in the world.", "Lake Baikal in Russia is the deepest lake in the world.", 2),
(S, "Which is the month of Allah (Shahrullah) in the Islamic calendar?", ["Shawwal", "Zil Qadah", "Ramadan", "Safar"], 2, "Ramadan is commonly called the month of Allah in Pakistani textbooks, because fasting is observed in it.", "Some sources also apply the title Shahrullah to Muharram or Rajab, so sources differ.", 5),
(S, "Which is the most populated city of Sindh?", ["Hyderabad", "Karachi", "Sukkur", "Larkana"], 1, "Karachi is the largest city of Sindh and of Pakistan by population.", "Karachi is the provincial capital of Sindh.", 2),
(S, "Which is the outermost planet of the solar system?", ["Uranus", "Saturn", "Pluto", "Neptune"], 3, "Neptune is the eighth and farthest planet from the Sun since Pluto was reclassified as a dwarf planet in 2006.", "Pluto was considered the ninth planet until 2006.", 5),
(S, "Which is the second largest continent by area?", ["Africa", "North America", "Europe", "Antarctica"], 0, "Asia is the largest and Africa is second largest with about 30.3 million square km.", "Africa is also the second most populous continent.", 2),
(S, "Which is the second most populous country of the world?", ["India", "United States", "China", "Indonesia"], 2, "India overtook China in 2023 to become the most populous country, so China is now second.", "In 2021-22 China was the most populous and India second.", 3),
(S, "Which is the smallest continent?", ["Europe", "Antarctica", "South America", "Australia"], 3, "Australia (Oceania) has an area of about 7.7 million square km, the smallest of the continents.", "Australia is the only continent that is also a single country.", 5),
(S, "Which is the world's largest uranium producing country?", ["Canada", "Kazakhstan", "Namibia", "Australia"], 1, "Kazakhstan has been the top uranium producer since 2009 and supplied about 39 percent of world mine output in 2024.", "Canada is second and Namibia third in recent World Nuclear Association data.", 2),
(S, "Which is the world's third longest river?", ["Yangtze", "Mississippi", "Yenisei", "Congo"], 0, "By length the Nile and Amazon are first and second, and the Yangtze in China is third at about 6,300 km.", "The Yangtze is the longest river in Asia.", 3),
(S, "Which mountain range is mainly associated with Afghanistan?", ["Hindu Kush", "Alps", "Andes", "Rockies"], 0, "The Hindu Kush range runs through central and northeastern Afghanistan into Pakistan.", "Tirich Mir in Chitral is the highest peak of the Hindu Kush.", 3),
(S, "Which is the highest mountain range of Pakistan?", ["Hindu Kush", "Karakoram", "Sulaiman", "Salt Range"], 1, "The Karakoram range contains K2 (8,611 m), the highest peak in Pakistan.", "Pakistan's mountain ranges include Himalaya, Karakoram, Hindu Kush, Sulaiman and Kirthar.", 3),
(S, "Which of the following countries is a member of SAARC?", ["Myanmar", "Iran", "Bhutan", "Thailand"], 2, "Bhutan is one of the eight SAARC members.", "SAARC members are Pakistan, India, Bangladesh, Sri Lanka, Nepal, Bhutan, Maldives and Afghanistan.", 2),
(S, "Which organization was formed by Turkey, Pakistan and Iran in 1964?", ["SEATO", "CENTO", "RCD", "OIC"], 2, "Regional Cooperation for Development (RCD) was formed in 1964 by Pakistan, Iran and Turkey.", "RCD was renamed the Economic Cooperation Organization (ECO) in 1985.", 3),
(S, "Which pass connects Pakistan with China?", ["Khyber Pass", "Bolan Pass", "Khunjerab Pass", "Lowari Pass"], 2, "The Khunjerab Pass in the Karakoram links Gilgit-Baltistan with Xinjiang in China.", "At about 4,693 m it is one of the highest paved border crossings in the world.", 3),
(S, "The Khyber Pass connects Pakistan with which country?", ["Iran", "China", "Afghanistan", "India"], 2, "The Khyber Pass links Peshawar in Pakistan with Jalalabad and Kabul in Afghanistan.", "Landi Kotal lies on the Khyber Pass.", 2),
(S, "Which prophet was swallowed by a fish and stayed in its belly?", ["Hazrat Younus (A.S)", "Hazrat Ayub (A.S)", "Hazrat Yaqub (A.S)", "Hazrat Idris (A.S)"], 0, "Hazrat Younus (A.S) was swallowed by a large fish and prayed to Allah from within its belly.", "He is also called Dhun-Nun and Surah Younus is named after him.", 5),
(S, "Which provincial assembly of Pakistan has the most seats?", ["Sindh (168)", "Punjab (371)", "Khyber Pakhtunkhwa (145)", "Balochistan (65)"], 1, "The Punjab Assembly has 371 seats (297 general, 66 women, 8 non-Muslim), the most of any province.", "Sindh has 168, KP 145 and Balochistan 65 seats.", 2),
(S, "Which SAARC country has the highest literacy rate?", ["Sri Lanka", "India", "Maldives", "Bhutan"], 2, "The Maldives has a literacy rate of about 98 to 99 percent, the highest among SAARC countries, with Sri Lanka close behind.", "Afghanistan and Pakistan are among the lowest in SAARC for literacy.", 4),
(S, "Which Sahabi married two daughters of the Holy Prophet (PBUH), Hazrat Ruqayyah and Hazrat Umm Kulthum?", ["Hazrat Abu Bakr (R.A)", "Hazrat Umar (R.A)", "Hazrat Ali (R.A)", "Hazrat Usman (R.A)"], 3, "Hazrat Usman (R.A) married Ruqayyah first and, after her death, Umm Kulthum.", "He is known as Dhun-Nurayn, the possessor of two lights.", 6),
(S, "Which Sahabi served the Holy Prophet (PBUH) for ten years?", ["Anas bin Malik (R.A)", "Abdullah bin Abbas (R.A)", "Abu Hurairah (R.A)", "Bilal (R.A)"], 0, "Anas bin Malik (R.A) was given to the Prophet as a servant at Madina as a boy and served him for about ten years.", "He narrated over 2,000 hadiths.", 4),
(S, "Which sea lies between Greece and Italy?", ["Aegean Sea", "Adriatic Sea", "Ionian Sea", "Tyrrhenian Sea"], 2, "The Ionian Sea lies between southern Italy and western Greece.", "The Aegean Sea lies east of Greece, between Greece and Turkey.", 5),
(S, "Which is the biggest sea of the world by area?", ["Mediterranean Sea", "Caribbean Sea", "South China Sea", "Arabian Sea"], 2, "The South China Sea covers about 3.5 million square km, the largest sea in the world.", "The Philippine Sea is sometimes listed as larger by some sources, so sources can differ.", 8),
(S, "Which surah of the Quran does not begin with Bismillah?", ["Surah At-Tawbah", "Surah Al-Anfal", "Surah Yasin", "Surah An-Naml"], 0, "Surah At-Tawbah (Bara'at) is the only surah that does not begin with Bismillah.", "Bismillah appears twice in Surah An-Naml, once at the start and once inside verse 30.", 2),
(S, "Which surah is described in the Quran as Ahsan-ul-Qasas (the best of stories)?", ["Surah Yusuf", "Surah Maryam", "Surah Al-Kahf", "Surah Taha"], 0, "Surah Yusuf tells the story of Hazrat Yusuf (A.S) and Allah calls it the best of stories.", "Surah Yusuf is the 12th surah of the Quran.", 2),
(S, "Which Surah is known as Ash-Shifa (the cure)?", ["Surah Al-Ikhlas", "Surah Yasin", "Surah Al-Fatiha", "Surah Al-Baqarah"], 2, "Surah Al-Fatiha is known by many names including Ash-Shifa because it is recited for healing.", "It is also called Umm-ul-Kitab and Sab'a al-Mathani.", 2),
(S, "In which Surah does Allah swear by time?", ["Surah Al-Qadr", "Surah Al-Asr", "Surah Al-Fil", "Surah Al-Humazah"], 1, "Surah Al-Asr begins with an oath by time (Wal-Asr).", "Surah Al-Asr is the 103rd surah and has three verses.", 2),
(S, "Which uncle of the Holy Prophet (PBUH) is mentioned by name in the Quran?", ["Hazrat Hamza", "Abu Talib", "Hazrat Abbas", "Abu Lahab"], 3, "Abu Lahab is named in Surah Al-Lahab (Al-Masad) which condemns him.", "He was the only enemy of the Prophet named in the Quran.", 2),
(S, "Which was the first mosque built by Prophet Muhammad (PBUH) and the first mosque of Islam in Madina?", ["Masjid-e-Nabawi", "Masjid Quba", "Masjid al-Qiblatayn", "Masjid al-Haram"], 1, "Masjid Quba was built by the Prophet (PBUH) on his arrival near Madina during the Hijrah.", "Masjid-e-Nabawi was built soon afterwards in Madina.", 6),
(S, "Which was the first prime minister of Pakistan to visit the USA?", ["Liaquat Ali Khan", "Khawaja Nazimuddin", "Muhammad Ali Bogra", "Huseyn Suhrawardy"], 0, "Liaquat Ali Khan visited the USA in May 1950, the first Pakistani prime minister to do so.", "He was Pakistan's first prime minister.", 2),
(S, "Which wife of Prophet Muhammad (PBUH) was the daughter of a Jewish leader?", ["Hazrat Safiyya (R.A)", "Hazrat Aisha (R.A)", "Hazrat Hafsa (R.A)", "Hazrat Zainab (R.A)"], 0, "Hazrat Safiyya bint Huyayy was from the Jewish tribe Banu Nadir and married the Prophet (PBUH) after Khaybar.", "She accepted Islam before the marriage.", 8),
(S, "Which wife of Prophet Muhammad (PBUH) was the daughter of Hazrat Umar Farooq (R.A)?", ["Hazrat Sauda (R.A)", "Hazrat Hafsa (R.A)", "Hazrat Umm Salama (R.A)", "Hazrat Aisha (R.A)"], 1, "Hazrat Hafsa bint Umar (R.A) married the Prophet (PBUH) in 3 AH.", "Hazrat Aisha was the daughter of Hazrat Abu Bakr (R.A).", 2),
(S, "Which woman accepted Islam first?", ["Hazrat Aisha (R.A)", "Hazrat Fatima (R.A)", "Hazrat Khadija (R.A)", "Hazrat Sumayya (R.A)"], 2, "Hazrat Khadija (R.A), wife of the Prophet (PBUH), was the first person and first woman to accept Islam.", "Hazrat Sumayya was the first martyr of Islam.", 7),
(S, "Who was the first child to accept Islam?", ["Hazrat Zaid bin Haritha (R.A)", "Hazrat Ali (R.A)", "Hazrat Abdullah bin Abbas (R.A)", "Hazrat Anas (R.A)"], 1, "Hazrat Ali (R.A) accepted Islam as a boy of about ten years, the first child to do so.", "Hazrat Abu Bakr (R.A) was the first adult man to accept Islam.", 5),
(S, "Which of the following is a permanent member of the UN Security Council?", ["Germany", "France", "Japan", "India"], 1, "The five permanent members are the USA, UK, France, Russia and China.", "Each permanent member holds the power of veto.", 3),
(S, "Who coined the name Pakistan?", ["Allama Iqbal", "Muhammad Ali Jauhar", "Chaudhry Rahmat Ali", "Liaquat Ali Khan"], 2, "Chaudhry Rahmat Ali coined the name Pakistan in 1933 in the pamphlet Now or Never.", "He was a Cambridge student when he proposed the name.", 2),
(S, "Who proposed digging the trench in the Battle of Khandaq (Ahzab)?", ["Hazrat Salman Farsi (R.A)", "Hazrat Ali (R.A)", "Hazrat Umar (R.A)", "Hazrat Khalid bin Walid (R.A)"], 0, "Hazrat Salman Farsi (R.A) suggested digging a trench, a Persian defence method, to protect Madina.", "The battle took place in 5 AH.", 2),
]
